/*
 * Linkr Bee X1.0 infrared transceiver.
 *
 * Hardware (MV013 rev X1.00):
 *   - Transmit: D7 IR LED (IR19-315C/TR8) switched by Q2 (WNM2021-3), gate on
 *     GPIO0 through R32 100R. The 38 kHz carrier is generated by LEDC channel
 *     0 on the same pin, so the firmware only turns the carrier on and off;
 *     it never has to time individual carrier cycles.
 *   - Receive: IRM_V538M3 demodulator output on GPIO1 (idle high, low during
 *     a mark). The 38 kHz demodulation happens in the module, so the firmware
 *     sees a clean mark/space train and decodes NEC frames with an edge
 *     interrupt.
 *
 * On top of the NEC codec the receiver also supports *learning*: the raw
 * mark/space train of any remote is captured, stored in NVS and replayed
 * through the same carrier, which covers remotes that are not NEC (RC5, Sony,
 * JVC, ...). Capture and blob rules live in ir_learn.c, which has no Zephyr
 * dependencies and is covered by a host test.
 */
#ifndef LINKR_IR_H_
#define LINKR_IR_H_

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "ir_learn.h"
#include "ir_nec.h"

struct linkr_ir_status {
	bool rx_enabled;
	bool have_frame;
	struct linkr_nec_frame last;
	uint32_t frames;
	uint32_t repeats;
	uint32_t glitches;
	/* Learning state and the learned-command table. */
	bool learning;
	uint8_t learn_slot;
	uint16_t learn_edges;
	uint8_t slots_used;
	uint16_t slot_edges[LINKR_IR_LEARN_SLOTS];
};

/* True when the board has the IR transceiver. */
bool linkr_ir_available(void);

/* Configure the receiver input/interrupt and the transmitter carrier. */
int linkr_ir_init(void);

/* Queue a NEC frame. `repeats` repeat frames follow the data frame. Returns
 * -ENODEV without a transmitter, -EAGAIN when the queue is full. */
int linkr_ir_send(uint16_t address, uint8_t command, uint8_t repeats);

/* Enable or disable NEC decoding of the receiver output. */
int linkr_ir_set_rx(bool enabled);

/* Snapshot the receiver counters, the most recent frame and the learned
 * command table. */
void linkr_ir_get_status(struct linkr_ir_status *status);

/* Forget the last frame and reset the counters (learned slots are kept). */
void linkr_ir_clear(void);

/*
 * Learning. The receiver interrupt captures intervals until the line goes
 * quiet for CONFIG_LINKR_BLE_BRIDGE_IR_LEARN_IDLE_MS, then the command layer
 * stores the frame in `slot` and persists it with Zephyr settings.
 */

/* Start a capture into `slot`. Returns -ENODEV without RX/TX hardware,
 * -EINVAL for a slot out of range. */
int linkr_ir_learn_start(uint8_t slot);

/* Stop a running capture. If enough intervals were captured the frame is
 * committed to the slot first. Returns 0 when a frame was stored, -EAGAIN
 * when the capture held no full frame, -EINVAL when no capture was running. */
int linkr_ir_learn_stop(void);

/* Replay learned command `slot`. Returns 0 when queued, -ENOENT for an empty
 * slot, -EAGAIN when the transmit queue is full, -ENODEV without a
 * transmitter. */
int linkr_ir_play(uint8_t slot);

/* Erase learned command `slot`. Returns 0 when cleared, -ENOENT when it was
 * already empty. */
int linkr_ir_forget(uint8_t slot);

/* Number of intervals stored in `slot`, or 0 when it is empty. */
uint16_t linkr_ir_slot_edges(uint8_t slot);

/*
 * Saved-command names. The name is free text (UTF-8, NUL-free) and is persisted
 * in NVS next to the waveform, so it belongs to the board rather than to the
 * client that typed it. An empty name clears the label; the waveform is not
 * touched. Commands carry the bytes hex-encoded, so spaces and non-ASCII bytes
 * need no quoting on the management channel.
 */

/* Store or clear (name == NULL or "") the name of `slot`.
 * Returns 0, -EINVAL for a slot out of range or an over-long name,
 * -ENODEV without learning support, -EIO when NVS rejects the write. */
int linkr_ir_slot_name_set(uint8_t slot, const char *name);

/* Copy the name of `slot` into `out` (always NUL-terminated). Returns its
 * length, 0 when unnamed, -EINVAL for a bad slot and -ENOSPC when `out` is too
 * small. */
int linkr_ir_slot_name_get(uint8_t slot, char *out, size_t out_len);

#endif /* LINKR_IR_H_ */
